  const ds = this.options.datastore;
  const form = document.getElementById('endQuest');

  form.addEventListener('submit', function(e) {
    e.preventDefault();
    
    // Create a FormData object to easily extract values
    const formData = new FormData(form);
    
    // 1. Process Gender
    let genderValue = formData.get('gender');
    // If user selected "Self Describe", try to get the text input
    if (genderValue === 'autoDescripcion') {
       const customText = formData.get('gender_text');
       // Save text if provided, otherwise keep the category name
       if (customText && customText.trim() !== "") {
           genderValue = `auto: ${customText.trim()}`;
       }
    }
    
    // 2. Get other fields directly
    const ageValue = formData.get('age');
    const yearValue = formData.get('year_study');

    // 3. Save to Datastore
    ds.set('demographics_gender', genderValue);
    ds.set('demographics_age', ageValue);
    ds.set('demographics_year_study', yearValue);

    // 4. Finish Experiment
    this.end();

  }.bind(this));

