  const userUni = ds.get('universidad_usuario') || 'Tu U';
  const userDegree = ds.get('carrera_usuario') || 'Tu Carrera';
  const userSafeId = `${userUni}_${userDegree}`.replace(/[^a-zA-Z0-9]/g, '_');
  const userAvatarId = ds.get(`avatar_${userSafeId}`) || 1;

  // --- 2. LÓGICA SIMPLIFICADA: SELECCIÓN Y GUARDADO DEL GRUPO "GAME 3" ---
  let p1Uni = ds.get('strategy_eval_p1_uni_game3');
  let p1Degree = ds.get('strategy_eval_p1_deg_game3');
  let p2Uni = ds.get('strategy_eval_p2_uni_game3');
  let p2Degree = ds.get('strategy_eval_p2_deg_game3');

  if (!p1Uni || !p2Uni) {
      const pool = [
        { uni: ds.get('universidad_jugador2'), degree: ds.get('carrera_jugador2') },
        { uni: ds.get('universidad_jugador3'), degree: ds.get('carrera_jugador3') },
        { uni: ds.get('universidad_jugador4'), degree: ds.get('carrera_jugador4') },
        { uni: ds.get('universidad_jugador5'), degree: ds.get('carrera_jugador5') },
        { uni: ds.get('universidad_jugador6'), degree: ds.get('carrera_jugador6') }
      ].filter(p => p.uni && p.degree);

      if (pool.length >= 2) {
          for (let i = pool.length - 1; i > 0; i--) {
              const j = Math.floor(Math.random() * (i + 1));
              [pool[i], pool[j]] = [pool[j], pool[i]];
          }
          p1Uni = pool[0].uni; p1Degree = pool[0].degree;
          p2Uni = pool[1].uni; p2Degree = pool[1].degree;
      } else {
          p1Uni = 'U de Prueba 1'; p1Degree = 'Carrera 1';
          p2Uni = 'U de Prueba 2'; p2Degree = 'Carrera 2';
      }

      ds.set('strategy_eval_p1_uni_game3', p1Uni);
      ds.set('strategy_eval_p1_deg_game3', p1Degree);
      ds.set('strategy_eval_p2_uni_game3', p2Uni);
      ds.set('strategy_eval_p2_deg_game3', p2Degree);
  }

  // --- 3. CÁLCULO DE COLORES/RELACIÓN ---
  function determineRelationship(uUni, uDeg, oUni, oDeg) {
      if (!oUni || !oDeg) return 'far';
      const sameUni = (uUni === oUni);
      const sameDeg = (uDeg === oDeg);
      if (sameUni && sameDeg) return "you";
      if (sameUni && !sameDeg) return "nearClose";
      if (!sameUni && sameDeg) return "nearFar";
      return "far";
  }

  const relP1 = determineRelationship(userUni, userDegree, p1Uni, p1Degree);
  const relP2 = determineRelationship(userUni, userDegree, p2Uni, p2Degree);

