      </td>
    `;
    tbody.appendChild(row);
  }

  // --- 6. CÁLCULO DINÁMICO DEL TOTAL ---
  tbody.addEventListener('input', function(e) {
      if (e.target.classList.contains('strategy-input')) {
          const avgOthers = parseInt(e.target.getAttribute('data-avg'), 10);
