          const displaySpan = document.getElementById(`total_display_${avgOthers}`);
          
          // Reset custom validity para que el borde rojo no se quede pegado permanentemente
          e.target.style.border = '1px solid #ccc';
          errorMsg.style.display = 'none';
          
          if (!isNaN(userInput) && userInput >= 0 && userInput <= 10) {
              const total = (avgOthers * 2) + userInput;
